	in := bufio.NewReader(os.Stdin)
	var n, m, a, b int
	fmt.Fscan(in, &n, &m, &a, &b)

	// Option 1: all single tickets
	costSingle := n * a

	// Option 2: full m-ride tickets plus remaining rides (single or extra m-ride)
	fullPasses := n / m
	remaining := n % m

	costFullPlusRemaining := fullPasses*b + min(remaining*a, b)

	// Also consider buying only m-ride tickets to cover all rides (ceil)
	fullPassesOnly := ((n + m - 1) / m) * b

	ans := min(costSingle, min(costFullPlusRemaining, fullPassesOnly))
	fmt.Println(ans)
}

func min(x, y int) int {
	if x < y {
		return x
	}
	return y
}

